import React, { useState, useEffect } from 'react';
import styles from './HeroBanner.module.css';

/**
 * Ultra-Premium Hero Banner Component for Artemis
 * Features:
 * - 4K cinematic background with volumetric lighting
 * - Flowing energy effects and atmospheric depth
 * - Responsive design for all devices
 * - Smooth animations and transitions
 * - Optimized for enterprise/SaaS landing pages
 */

const HeroBanner = ({
  headline = 'Global Consulting Reimagined',
  subheadline = 'Enterprise-grade technology solutions for tomorrow\'s challenges',
  primaryCTA = { label: 'Explore Solutions', onClick: () => {} },
  secondaryCTA = { label: 'Learn More', onClick: () => {} },
  showScrollIndicator = true,
}) => {
  const [isLoaded, setIsLoaded] = useState(false);

  useEffect(() => {
    // Trigger animation after component mounts
    setIsLoaded(true);

    // Optional: Add scroll event listener for parallax effect
    const handleScroll = () => {
      const scrollY = window.scrollY;
      const bgElement = document.querySelector(`.${styles.heroBackground}`);
      
      if (bgElement && scrollY < window.innerHeight) {
        // Subtle parallax effect
        bgElement.style.transform = `translateY(${scrollY * 0.5}px)`;
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <div className={styles.heroContainer}>
      {/* Ultra-premium background layer */}
      <div className={styles.heroBackground} />
      
      {/* Animated atmospheric overlay for depth */}
      <div className={styles.backgroundOverlay} />
      
      {/* Dark gradient overlay for text readability */}
      <div className={styles.contentOverlay} />

      {/* Main content */}
      <div className={styles.heroContent}>
        {/* Headline with gradient accent */}
        <h1 className={styles.heroHeadline}>
          {headline}
        </h1>

        {/* Subheadline */}
        <p className={styles.heroSubheadline}>
          {subheadline}
        </p>

        {/* Call-to-Action Buttons */}
        <div className={styles.heroCTA}>
          <button
            className={`${styles.ctaButton} ${styles.ctaPrimary}`}
            onClick={primaryCTA.onClick}
            aria-label={primaryCTA.label}
          >
            {primaryCTA.label}
          </button>
          <button
            className={`${styles.ctaButton} ${styles.ctaSecondary}`}
            onClick={secondaryCTA.onClick}
            aria-label={secondaryCTA.label}
          >
            {secondaryCTA.label}
          </button>
        </div>
      </div>

      {/* Scroll Indicator */}
      {showScrollIndicator && (
        <div className={styles.scrollIndicator}>
          <div className={styles.scrollIcon} />
        </div>
      )}
    </div>
  );
};

export default HeroBanner;
